import { createServer } from 'node:http';
import { readFile, writeFile } from 'node:fs/promises';
import { existsSync } from 'node:fs';
import { randomUUID } from 'node:crypto';

const PORT = process.env.PORT || 3000;
const DB_PATH = './books.json';

let db = { books: [] };

async function loadDb() {
  if (existsSync(DB_PATH)) {
    const raw = await readFile(DB_PATH, 'utf8');
    db = JSON.parse(raw);
  }
}

async function saveDb() {
  await writeFile(DB_PATH, JSON.stringify(db, null, 2));
}

function escapeHtml(str) {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function layout(title, body) {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
  <style>
    * { box-sizing: border-box; }
    body {
      font-family: system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      max-width: 720px;
      margin: 0 auto;
      padding: 1.5rem;
      line-height: 1.5;
      color: #222;
      background: #fafafa;
    }
    h1, h2 { margin: 0 0 1rem; }
    h1 { font-size: 1.75rem; }
    h2 { font-size: 1.25rem; margin-top: 2rem; }
    a { color: #2563eb; text-decoration: none; }
    a:hover { text-decoration: underline; }
    .card {
      background: #fff;
      border: 1px solid #e5e7eb;
      border-radius: 0.5rem;
      padding: 1rem;
      margin-bottom: 1rem;
    }
    .card h3 { margin: 0 0 0.25rem; font-size: 1.1rem; }
    .card .meta { color: #6b7280; font-size: 0.9rem; margin-bottom: 0.5rem; }
    .card .actions { display: flex; gap: 0.75rem; align-items: center; margin-top: 0.75rem; }
    form { margin: 0; }
    label { display: block; margin-bottom: 0.25rem; font-weight: 500; }
    input[type="text"], textarea {
      width: 100%;
      padding: 0.5rem;
      border: 1px solid #d1d5db;
      border-radius: 0.375rem;
      font: inherit;
    }
    textarea { min-height: 6rem; resize: vertical; }
    .field { margin-bottom: 1rem; }
    button {
      background: #2563eb;
      color: #fff;
      border: none;
      padding: 0.5rem 1rem;
      border-radius: 0.375rem;
      font: inherit;
      cursor: pointer;
    }
    button:hover { background: #1d4ed8; }
    button.secondary { background: #fff; color: #2563eb; border: 1px solid #2563eb; }
    button.secondary:hover { background: #eff6ff; }
    button.finish { background: #16a34a; }
    button.finish:hover { background: #15803d; }
    .empty { color: #6b7280; font-style: italic; }
    .notes { background: #f3f4f6; padding: 0.75rem; border-radius: 0.375rem; margin-top: 0.75rem; }
    .notes pre { margin: 0; white-space: pre-wrap; font-family: inherit; }
    .badge { display: inline-block; background: #dcfce7; color: #166534; padding: 0.125rem 0.5rem; border-radius: 9999px; font-size: 0.8rem; font-weight: 500; }
  </style>
</head>
<body>
  ${body}
</body>
</html>`;
}

function renderIndex() {
  const reading = db.books.filter((b) => !b.finished);
  const finished = db.books.filter((b) => b.finished);

  const list = (books, emptyMsg) => {
    if (books.length === 0) return `<p class="empty">${emptyMsg}</p>`;
    return books
      .map(
        (book) => `
      <div class="card">
        <h3><a href="/books/${book.id}">${escapeHtml(book.title)}</a></h3>
        <div class="meta">${escapeHtml(book.author)}</div>
        <div class="actions">
          <a href="/books/${book.id}">View details</a>
          ${
            !book.finished
              ? `<form action="/books/${book.id}/finish" method="POST"><button class="finish" type="submit">Mark finished</button></form>`
              : '<span class="badge">Finished</span>'
          }
        </div>
      </div>`
      )
      .join('');
  };

  const body = `
    <h1>My Reading List</h1>
    <div class="card">
      <h2>Add a book</h2>
      <form action="/books" method="POST">
        <div class="field">
          <label for="title">Title</label>
          <input id="title" name="title" type="text" required>
        </div>
        <div class="field">
          <label for="author">Author</label>
          <input id="author" name="author" type="text" required>
        </div>
        <div class="field">
          <label for="notes">Notes</label>
          <textarea id="notes" name="notes" placeholder="What do you think so far?"></textarea>
        </div>
        <button type="submit">Add book</button>
      </form>
    </div>

    <h2>Currently reading</h2>
    ${list(reading, 'No books in progress. Add one above.')}

    <h2>Finished</h2>
    ${list(finished, 'No finished books yet.')}
  `;

  return layout('My Reading List', body);
}

function renderBook(book) {
  const body = `
    <p><a href="/">← Back to list</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <div class="card">
      <div class="meta"><strong>Author:</strong> ${escapeHtml(book.author)}</div>
      ${book.finished ? '<span class="badge">Finished</span>' : ''}
      <div class="notes">
        <strong>Notes</strong>
        <pre>${escapeHtml(book.notes || 'No notes yet.')}</pre>
      </div>
    </div>

    <div class="card">
      <h2>Edit notes</h2>
      <form action="/books/${book.id}/notes" method="POST">
        <div class="field">
          <textarea name="notes">${escapeHtml(book.notes || '')}</textarea>
        </div>
        <button type="submit">Save notes</button>
      </form>
      ${
        !book.finished
          ? `<form action="/books/${book.id}/finish" method="POST" style="margin-top:1rem"><button class="finish" type="submit">Mark finished</button></form>`
          : ''
      }
    </div>
  `;

  return layout(book.title, body);
}

function parseBody(req) {
  return new Promise((resolve, reject) => {
    let body = '';
    req.on('data', (chunk) => (body += chunk));
    req.on('end', () => {
      const params = new URLSearchParams(body);
      const result = {};
      for (const [key, value] of params) {
        result[key] = value;
      }
      resolve(result);
    });
    req.on('error', reject);
  });
}

async function redirect(res, location) {
  res.writeHead(302, { Location: location });
  res.end();
}

const server = createServer(async (req, res) => {
  try {
    const url = new URL(req.url, `http://${req.headers.host}`);
    const path = decodeURIComponent(url.pathname);

    if (req.method === 'GET' && path === '/') {
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(renderIndex());
      return;
    }

    const bookMatch = path.match(/^\/books\/([^/]+)$/);
    if (req.method === 'GET' && bookMatch) {
      const book = db.books.find((b) => b.id === bookMatch[1]);
      if (!book) {
        res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(layout('Not Found', '<h1>Book not found</h1><p><a href="/">← Back to list</a></p>'));
        return;
      }
      res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
      res.end(renderBook(book));
      return;
    }

    if (req.method === 'POST' && path === '/books') {
      const body = await parseBody(req);
      if (!body.title || !body.author) {
        res.writeHead(400, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(layout('Error', '<h1>Bad request</h1><p>Title and author are required.</p>'));
        return;
      }
      const book = {
        id: randomUUID(),
        title: body.title.trim(),
        author: body.author.trim(),
        notes: (body.notes || '').trim(),
        finished: false,
        createdAt: new Date().toISOString(),
      };
      db.books.unshift(book);
      await saveDb();
      return redirect(res, '/');
    }

    const finishMatch = path.match(/^\/books\/([^/]+)\/finish$/);
    if (req.method === 'POST' && finishMatch) {
      const book = db.books.find((b) => b.id === finishMatch[1]);
      if (!book) {
        res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(layout('Not Found', '<h1>Book not found</h1>'));
        return;
      }
      book.finished = true;
      book.finishedAt = new Date().toISOString();
      await saveDb();
      return redirect(res, `/books/${book.id}`);
    }

    const notesMatch = path.match(/^\/books\/([^/]+)\/notes$/);
    if (req.method === 'POST' && notesMatch) {
      const book = db.books.find((b) => b.id === notesMatch[1]);
      if (!book) {
        res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(layout('Not Found', '<h1>Book not found</h1>'));
        return;
      }
      const body = await parseBody(req);
      book.notes = (body.notes || '').trim();
      await saveDb();
      return redirect(res, `/books/${book.id}`);
    }

    res.writeHead(404, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(layout('Not Found', '<h1>Not found</h1><p><a href="/">← Back to list</a></p>'));
  } catch (err) {
    console.error(err);
    res.writeHead(500, { 'Content-Type': 'text/html; charset=utf-8' });
    res.end(layout('Error', '<h1>Something went wrong</h1>'));
  }
});

await loadDb();
server.listen(PORT, () => {
  console.log(`Reading list app running at http://localhost:${PORT}`);
});

